<?php
namespace App\Filament\Resources\Registrations\Schemas;
use Filament\Forms\Components\DatePicker; use Filament\Forms\Components\DateTimePicker; use Filament\Forms\Components\Select; use Filament\Forms\Components\TextInput; use Filament\Forms\Components\Textarea; use Filament\Forms\Components\Toggle; use Filament\Schemas\Schema;
class RegistrationForm { public static function configure(Schema $schema): Schema { return $schema->components([Select::make('user_id')->relationship('user','name')->searchable()->required(), Select::make('event_id')->relationship('event','name')->required(), Select::make('package_id')->relationship('package','name')->required(), Select::make('status')->options(['draft'=>'Draft','pending'=>'Pending','confirmed'=>'Confirmed','cancelled'=>'Cancelled','waiting_list'=>'Waiting list'])->required(), Select::make('payment_status')->options(['unpaid'=>'Unpaid','deposit_invoiced'=>'Deposit invoiced','deposit_paid'=>'Deposit paid','fully_paid'=>'Fully paid','refunded'=>'Refunded','credited'=>'Credited'])->required(), Toggle::make('single_room_requested'), TextInput::make('roommate_preference'), Toggle::make('checked_luggage_requested'), Textarea::make('notes'), DateTimePicker::make('confirmed_at')]); } }
